inline FSPT::FSPT(const FSPT &o)
      : POLICY_ID(o.POLICY_ID),
        POLICY_VERSION(o.POLICY_VERSION),
        PROVIDER_PEER_ID(o.PROVIDER_PEER_ID),
        LISTING_ID(o.LISTING_ID),
        STREAM_ID(o.STREAM_ID),
        SCHEMA_CODE(o.SCHEMA_CODE),
        SCHEMA_HASH(o.SCHEMA_HASH),
        ALLOWED_OPERATIONS(o.ALLOWED_OPERATIONS),
        KEY_SCOPE(o.KEY_SCOPE),
        KEY_EPOCH(o.KEY_EPOCH),
        VALID_FROM(o.VALID_FROM),
        EXPIRES_AT(o.EXPIRES_AT),
        REVOCATION_STATUS(o.REVOCATION_STATUS),
        REVOKED_AT(o.REVOKED_AT),
        REVOCATION_REASON(o.REVOCATION_REASON),
        PROVIDER_SIGNATURE(o.PROVIDER_SIGNATURE) {
  AUDIENCES.reserve(o.AUDIENCES.size());
  for (const auto &AUDIENCES_ : o.AUDIENCES) { AUDIENCES.emplace_back((AUDIENCES_) ? new FieldStreamAudienceT(*AUDIENCES_) : nullptr); }
  RULES.reserve(o.RULES.size());
  for (const auto &RULES_ : o.RULES) { RULES.emplace_back((RULES_) ? new FieldStreamRuleT(*RULES_) : nullptr); }
}

