  std::swap(KEY_SCOPE, o.KEY_SCOPE);
  std::swap(KEY_EPOCH, o.KEY_EPOCH);
  std::swap(VALID_FROM, o.VALID_FROM);
  std::swap(EXPIRES_AT, o.EXPIRES_AT);
